package vn.xuannhashop.business.maintenance.application;
import java.util.*;
import java.time.LocalDate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import vn.xuannhashop.business.shared.*;
import vn.xuannhashop.business.shared.security.ActorContext;
import vn.xuannhashop.business.shared.audit.ActivityService;
import vn.xuannhashop.business.inventory.application.EquipmentApplication;
import vn.xuannhashop.business.reservation.application.ReservationApplication;
@Service public class WarrantyService implements WarrantyApplication {
    private final WarrantyRepository r;private final EquipmentApplication equipment;private final ReservationApplication reservations;private final ActorContext actor;private final Commands commands;private final ActivityService audit;
    public WarrantyService(WarrantyRepository r,EquipmentApplication equipment,ReservationApplication reservations,ActorContext actor,Commands commands,ActivityService audit){this.r=r;this.equipment=equipment;this.reservations=reservations;this.actor=actor;this.commands=commands;this.audit=audit;}
    public Map<String,Object> overview(){actor.require("OWNER","MANAGER","INVENTORY","TECHNICIAN");return r.overview();}
    @Transactional public UUID coverage(Coverage c,String key){actor.require("OWNER","TECHNICIAN");if(c==null||c.equipmentId()==null||c.expectedVersion()==null||c.expectedVersion()<0||c.startsOn()==null||c.endsOn()==null||c.endsOn().isBefore(c.startsOn()))throw DomainException.bad("Cần mã thiết bị, phiên bản và thời hạn bảo hành hợp lệ.");Checks.text(c.provider(),160,"Đơn vị bảo hành");Checks.text(c.documentRef(),180,"Hồ sơ bảo hành");Checks.text(c.terms(),4000,"Điều kiện bảo hành");return commands.once(key,"WARRANTY_COVERAGE:"+c,()->{reservations.lock(c.equipmentId());equipment.asset(c.equipmentId());var old=r.coverage(c.equipmentId());long version=old==null?0:((Number)old.get("version")).longValue();if(version!=c.expectedVersion())throw DomainException.conflict("Hồ sơ bảo hành đã đổi, tải lại trước khi sửa.");r.coverage(c,actor.username());audit.record("WARRANTY_COVERAGE_UPDATED",c.equipmentId(),"v"+(version+1));return c.equipmentId();});}
    @Transactional public UUID open(UUID id,String problem,String reference,String key){actor.require("OWNER","TECHNICIAN");Checks.text(problem,1000,"Vấn đề cần bảo hành");Checks.text(reference,180,"Mã tiếp nhận đối tác");return commands.once(key,"WARRANTY_OPEN:"+id+":"+problem+":"+reference,()->{reservations.requireIdle(id);var c=r.coverage(id);if(c==null||((LocalDate)c.get("starts_on")).isAfter(LocalDate.now())||((LocalDate)c.get("ends_on")).isBefore(LocalDate.now()))throw DomainException.conflict("Chưa có hồ sơ bảo hành còn hiệu lực.");equipment.transition(id,Set.of("READY","AWAIT_ACCEPTANCE","AWAIT_INSPECTION","MAINTENANCE"),"MAINTENANCE");UUID claim=UUID.randomUUID();r.open(claim,id,c,problem,reference,actor.username());audit.record("WARRANTY_OPENED",id,reference);return claim;});}
    @Transactional public void close(UUID id,String outcome,String result,String key){actor.require("OWNER","TECHNICIAN");if(outcome==null||!Set.of("REPAIRED","REPLACED","DECLINED","UNRESOLVED").contains(outcome))throw DomainException.bad("Chọn kết quả bảo hành.");Checks.text(result,1000,"Biên bản trả về và kết quả");commands.once(key,"WARRANTY_CLOSE:"+id+":"+outcome+":"+result,()->{var c=r.claim(id);if(c==null)throw DomainException.missing();if(!c.get("status").equals("OPEN"))throw DomainException.conflict("Hồ sơ bảo hành đã kết thúc.");UUID e=(UUID)c.get("equipment_id");reservations.lock(e);r.close(id,outcome,result,actor.username());equipment.transition(e,Set.of("MAINTENANCE"),"AWAIT_INSPECTION");audit.record("WARRANTY_CLOSED",e,outcome+"; "+result);return id;});}
}
